                            flightControlOut: Drone_Lifecycle_Energy_Governor.FlightControlOutputs => B,
                            propulsionPermissionOut: Drone_Lifecycle_Energy_Governor.PropulsionPermission.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val pilotStatusOutValue: Drone_Lifecycle_Energy_Governor.PilotStatus = get_pilotStatusOut().get
    if(!pilotStatusOut(pilotStatusOutValue)) {
      testFailures = testFailures :+ st"'pilotStatusOut' did not match expected: value of the outgoing data port is ${pilotStatusOutValue}"
    }
    val chargePermissionOutValue: Drone_Lifecycle_Energy_Governor.ChargePermission.Type = get_chargePermissionOut().get
    if(!chargePermissionOut(chargePermissionOutValue)) {
      testFailures = testFailures :+ st"'chargePermissionOut' did not match expected: value of the outgoing data port is ${chargePermissionOutValue}"
    }
    val flightControlOutValue: Drone_Lifecycle_Energy_Governor.FlightControlOutputs = get_flightControlOut().get
    if(!flightControlOut(flightControlOutValue)) {
      testFailures = testFailures :+ st"'flightControlOut' did not match expected: value of the outgoing data port is ${flightControlOutValue}"
    }
    val propulsionPermissionOutValue: Drone_Lifecycle_Energy_Governor.PropulsionPermission.Type = get_propulsionPermissionOut().get
    if(!propulsionPermissionOut(propulsionPermissionOutValue)) {
      testFailures = testFailures :+ st"'propulsionPermissionOut' did not match expected: value of the outgoing data port is ${propulsionPermissionOutValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


